<script lang="ts">
 import {untrack} from 'svelte';
 import {flushActiveSave} from '$lib/player/active-save';
 import {createInterfaceLanguage} from '$lib/i18n/context.svelte';import LanguageSelector from '$lib/i18n/LanguageSelector.svelte';
 import '../app.css';import {navigating} from '$app/state';import {browser} from '$app/environment';import {setStorageContext} from '$lib/storage/local-adventures';import {request} from '$lib/platform/client';
 let {children,data}=$props();const ui=createInterfaceLanguage(untrack(()=>data.locale));let notice=$state(''),bar:HTMLElement|undefined=$state();
 $effect(()=>{if(!bar)return;const current=bar,observer=new ResizeObserver(()=>document.documentElement.style.setProperty('--platform-bar-height',current.offsetHeight+'px'));observer.observe(current);return()=>{observer.disconnect();document.documentElement.style.removeProperty('--platform-bar-height');};});
 function configureStorage(){setStorageContext(data.principal?.tenant?.id?`${data.principal.user.id}:${data.principal.tenant.id}`:null);}if(browser)configureStorage();
 $effect(()=>{setStorageContext(data.principal?.tenant?.id?`${data.principal.user.id}:${data.principal.tenant.id}`:null);});
 async function session(action:string,body={}){try{await flushActiveSave();await request('/api/auth/'+action,body);location.href=action==='impersonate'?'/superadmin':'/';}catch(e){notice=(e as Error).message;}}
 async function logoutPlayer(){try{await flushActiveSave();await request('/api/player/logout',{});location.reload();}catch(e){notice=(e as Error).message;}}
</script>
<nav bind:this={bar} class:acting={data.principal?.impersonating} class="platform-bar" aria-label={ui.text("Cuenta y espacio")}>{#if data.principal}<a href="/">{ui.text("Aventuras públicas")}</a><a href={data.principal.tenant?'/admin':'/superadmin'}>{data.principal.tenant?.name??ui.text("Superadministración")}</a><span>{data.principal.impersonating?`${ui.locale==='en'?ui.text("Acting as"):ui.text("Actuando como")} ${data.principal.user.username} · ${ui.locale==='en'?ui.text("session of"):ui.text("sesión de")} ${data.principal.actor.username}`:data.principal.user.username}</span>{#if data.principal.impersonating}<button onclick={()=>session('impersonate')}>{ui.text("Volver a superadmin")}</button>{:else}<a href="/account">{ui.text("Mi cuenta")}</a>{/if}<button onclick={()=>session('logout')}>{ui.text("Salir")}</button>{/if}{#if data.player}<span>{ui.text("Jugador")}: {data.player.username}</span><button onclick={logoutPlayer}>{ui.text("Salir como jugador")}</button>{/if}<div class="global-language"><LanguageSelector/></div></nav>
{#if notice}<p role="alert">{ui.text(notice)}</p>{/if}
{#if navigating.to}<div class="navigation-loading" role="status">{ui.text("Abriendo pantalla…")}</div>{/if}
{@render children()}
<style>.navigation-loading{position:fixed;top:12px;left:50%;transform:translateX(-50%);z-index:1000;padding:9px 16px;border:1px solid #d4dfcf;border-radius:20px;background:#f8fbf4;color:#355440;box-shadow:0 3px 14px #183a3118;font:12px system-ui;pointer-events:none}.platform-bar{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:10px 24px;background:#183a31;color:white;font:13px system-ui;position:relative;z-index:100}.platform-bar.acting{background:#654612}.platform-bar a{color:inherit;text-decoration:underline}.global-language{margin-left:auto}.platform-bar span{margin-left:auto}.platform-bar button{color:inherit;border:1px solid #ffffff60;background:transparent;border-radius:6px;padding:6px 10px;cursor:pointer}</style>
